import json
from itertools import product
from sympy import Matrix
from sympy.matrices.normalforms import smith_normal_form
from sympy.polys.domains import ZZ

lower=(2,2,0,0,0)
upper=(4,4,4,4,4)
degrees=list(range(4,21))
hdegrees=(1,2,3,4)

def partitions_in_box_of_degree(d):
    ans=[]
    def rec(pos, prev, rem, a):
        if pos==5:
            if rem==0 and all(a[i]>=lower[i] for i in range(5)):
                ans.append(tuple(a))
            return
        lo=lower[pos]
        hi=min(prev,upper[pos],rem)
        for x in range(hi,lo-1,-1):
            rec(pos+1,x,rem-x,a+[x])
    rec(0,upper[0],d,[])
    return ans

def horizontal_strip(lam, nu):
    # lambda subset nu and each column receives at most one new box.
    if any(lam[i]>nu[i] for i in range(5)):
        return False
    if sum(nu)-sum(lam) < 0:
        return False
    for col in range(1,5):
        old=sum(x>=col for x in lam)
        new=sum(x>=col for x in nu)
        if new-old not in (0,1):
            return False
    return True

results=[]
for e in degrees:
    cols=partitions_in_box_of_degree(e)
    colindex={x:i for i,x in enumerate(cols)}
    rows=[]
    for t in hdegrees:
        for lam in partitions_in_box_of_degree(e-t):
            coeff=[0]*len(cols)
            for nu in cols:
                if sum(nu)-sum(lam)==t and horizontal_strip(lam,nu):
                    coeff[colindex[nu]]=1
            rows.append({'hDegree':t,'source':list(lam),'coefficients':coeff})
    matrix=[r['coefficients'] for r in rows]
    if matrix:
        M=Matrix(matrix)
        rank=M.rank()
        D=smith_normal_form(M,domain=ZZ)
        diag=[]
        for i in range(min(D.rows,D.cols)):
            x=int(D[i,i])
            if x:
                diag.append(abs(x))
    else:
        rank=0; diag=[]
    divisors=[]; acc=1
    for x in diag:
        acc*=x; divisors.append(acc)
    torsion=[x for x in diag if x>1]
    results.append({'degree':e,'columns':[list(x) for x in cols], 'rows':rows,
                    'matrixShape':[len(rows),len(cols)], 'rank':rank,
                    'determinantalDivisors':divisors, 'smithDiagonal':diag,
                    'quotientFreeRank':len(cols)-rank,
                    'torsionInvariantFactors':torsion,
                    'torsionDecomposition':(['Z/'+str(x) for x in torsion] if torsion else [])})
print(json.dumps({'input':{'lower':list(lower),'upper':list(upper),'degrees':degrees,'hDegrees':list(hdegrees)},'degreeResults':results,'outsideRange':{'J_degree_lt_4':0,'J_degree_gt_20':0,'quotient_degree_lt_4':0,'quotient_degree_gt_20':0}},separators=(',',':')))
